list_blog_categories.code:
final response = await client.blogCategories
    .listBlogCategories(queryParams: {'limit': 20, 'offset': 0});
final categories = (response.map as Map)['blog_categories'] as List;
for (final category in categories) {
  print('${(category as Map)['id']} ${category['name']} ${category['url']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

